\label{thm:descent-invertibility}
Under \eqref{eq:lyaprange},
\begin{equation}
\label{eq:lyapineq}
 V(\bar F_h(z))\le V(z)-c_h(\sin z)^TK\sin z,
\end{equation}
so $V(\bar F_h(z))<V(z)$ for $z\notin\operatorname{Crit}(V)$. Under
\eqref{eq:diffeorange}, $\bar F_h$ is a diffeomorphism of $\mathcal Z$.

At a critical point $p$,
\begin{equation}
\label{eq:linearisation}
 D\bar F_h(p)|_E=I-hK_0H_p.
\end{equation}
The matrix $K_0H_p$ is similar to the symmetric matrix
$K_0^{1/2}H_pK_0^{1/2}$ and has the same inertia as $H_p$.  Its
eigenvalues $\eta$ are real and satisfy $|\eta|\le\Lambda_{n}$.  Under
\eqref{eq:lyaprange}, positive $\eta$ give $|1-h\eta|<1$, whereas negative
$\eta$ give $1-h\eta>1$.  Non-degeneracy excludes $\eta=0$.

\label{cor:full-convergence}
Under \eqref{eq:lyaprange}, every orbit of \(F_h\) converges to a
fixed point.

\label{prop:null-preimages}
For every \(h>0\), \(\bar F_h^{-1}(N)\) is null whenever
\(N\subset\mathcal Z\) is null.

\label{thm:classification}
If $n\not\equiv0\pmod4$, every critical point of $V$ is represented
exactly once by \eqref{eq:critconfig}--\eqref{eq:alphakr}, is
non-degenerate, and satisfies
\begin{equation}
\label{eq:index-general}
 \operatorname{ind}(z)=
 \begin{cases}
 n-1-k,&c_{k,r}>0,\\
 k,&c_{k,r}<0,
 \end{cases}
 \qquad
 V(z)=d_kc_{k,r}.
\end{equation}

\label{cor:critical-count}
If $n\not\equiv0\pmod4$, then $V$ is Morse with
$n\binom{n-1}{\lfloor (n-1)/2\rfloor}$ critical points.

\label{cor:critical-counts-4l}
If $n\equiv0\pmod4$, there are
\begin{equation}
\label{eq:numberisolated4l}
 \frac{n+2}{2}\binom{n}{n/2}-2^{n},
\end{equation}
isolated critical points and
\begin{equation}
\label{eq:numbercircles}
 \frac12\binom{n}{n/2}
\end{equation}
critical circles.

\label{rem:notextrema}
Near \(p_+\), write \(z=p_++y\) with \(y\in E\). Taylor expansion gives
\begin{equation*}
 V(p_++y)=\frac16\sum_{i=1}^{n}y_i^3+O(\|y\|^5).
\end{equation*}
The linear term vanishes because \(\mathbf1^Ty=0\). Taking
\(y=(2t,-t,-t,0,\ldots,0)\) gives \(V=t^3+O(t^5)\), with both signs
arbitrarily close to \(p_+\). At \(p_-\) the expansion has the opposite
sign. Hence neither intersection is a local extremum.

\label{prop:twistmultipliers}
At the uniform $q$-twist, the multipliers of $D\bar F_h|_E$ are
$1+hc_q\lambda_j$, $j=1,\ldots,n-1$.

\label{thm:minima}
The local minima of $V$ are the uniform twists with $c_q<0$, and such a
twist is a sink if and only if
\begin{equation}
\label{eq:exactsinkrange}
 0<h<\frac{2}{-c_q\Lambda_{n}}
\end{equation}
holds. Under \eqref{eq:lyaprange}, these twists are exactly the sinks of
$\bar F_h$.

\label{cor:number-sinks}
Under \eqref{eq:lyaprange}, the number of sinks is
\begin{equation}
\label{eq:numsinks}
 \begin{cases}
  2\left\lfloor\dfrac{n+1}{4}\right\rfloor,
       &n\text{ odd},\\[1.2ex]
  \dfrac{n}{2},&n\equiv2\pmod4,\\[1.2ex]
  \dfrac{n-2}{2},&n\equiv0\pmod4.
 \end{cases}
\end{equation}

\label{cor:absolute-minima}
If $n$ is even, $V$ has the unique absolute minimum
\begin{equation}
\label{eq:antiphase}
 z=\pi\mathbf1;
\end{equation}
if $n$ is odd, its absolute minima are
\begin{equation}
\label{eq:absolute-minima}
 z=\left(\pi-\frac{\pi}{n}\right)\mathbf1,
 \qquad
 z=\left(\pi+\frac{\pi}{n}\right)\mathbf1.
\end{equation}
The minimum value is
\begin{equation}
\label{eq:absolutemin}
 \min_{z\in\mathcal Z}V(z)=
 \begin{cases}
  -n,&n\text{ even},\\[.5ex]
  -n\cos\dfrac{\pi}{n},&n\text{ odd}.
 \end{cases}
\end{equation}

\label{prop:strict-saddle-basins}
Under \eqref{eq:lyaprange}, \(\mathcal B(\mathcal S)\) has zero
measure.

\label{lem:local-normal-form}
As \(y\to0\) in \(E\),
\begin{align}
 G_h(y)&=y-h\operatorname{grad}_g P_3(y)+O(\|y\|_g^4),
 \label{eq:local-map-cubic}\\
 W(y)&=P_3(y)-\frac1{120}\sum_{i=1}^ny_i^5+O(\|y\|_g^7).
 \label{eq:local-potential-cubic}
\end{align}
Moreover,
\begin{equation}
\label{eq:harmonic-cubic}
 \Delta_gP_3=0,
\end{equation}
and, for \(y=ru\), the blown-up map satisfies
\begin{align}
 r^+&=r-3h\phi(u)r^2
 +\frac{h^2}{2}\|\operatorname{grad}_{S_g}\phi(u)\|_g^2r^3
 +O(r^4),
 \label{eq:radial-blowup}\\
 u^+&=u-hr\operatorname{grad}_{S_g}\phi(u)+O(r^2).
 \label{eq:angular-blowup}
\end{align}

\label{lem:angular-limit}
For every such orbit, there is \(\kappa\ge0\) such that
\begin{equation}
\label{eq:angular-critical-limit}
 \phi(u_k)\to \kappa,
 \qquad
 \operatorname{dist}\bigl(u_k,
 \operatorname{Crit}(\phi)\cap\phi^{-1}(\kappa)\bigr)\to0.
\end{equation}

\label{prop:degenerate-basins}
If \(4\mid n\), then under \eqref{eq:lyaprange} the basins
\(\mathcal B(p_+)\) and \(\mathcal B(p_-)\) have zero measure.

\label{lem:slow-dichotomy}
Every solution of \eqref{eq:slow-dichotomy-system} that converges to zero
satisfies
\begin{equation}
\label{eq:slow-dichotomy-decay}
 \|x_k\|\le Ce^{-\gamma\sigma_k}
\end{equation}
for some \(C,\gamma>0\).
